<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('manage_users');
$locs=db()->query('SELECT * FROM locations WHERE active=1 ORDER BY code')->fetchAll();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';$role=$_POST['role']??'';$allowed=['manager','cashier','godown','auditor'];$chosenLocs=array_values(array_unique(array_filter(array_map('intval',$_POST['locations']??[]))));if(!in_array($role,$allowed,true)||strlen($password)<10||$name===''||$username==='')$err='Name, username, valid role and 10+ character password are required.';elseif(!$chosenLocs)$err='Assign at least one stock location for staff/report access.';else try{license_require_user_capacity();db()->beginTransaction();$st=db()->prepare('INSERT INTO users(name,username,password_hash,role,active) VALUES(?,?,?,?,1)');$st->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$role]);$uid=(int)db()->lastInsertId();$locSt=db()->prepare('INSERT INTO user_locations(user_id,location_id) VALUES(?,?)');foreach($chosenLocs as $lid)$locSt->execute([$uid,$lid]);db()->commit();audit('USER_CREATE','user',$uid,['role'=>$role]);redirect('users.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err='Could not create user. Username may already exist.';}}
$rows=db()->query("SELECT u.*,GROUP_CONCAT(l.code ORDER BY l.code SEPARATOR ', ') locations FROM users u LEFT JOIN user_locations ul ON ul.user_id=u.id LEFT JOIN locations l ON l.id=ul.location_id GROUP BY u.id ORDER BY u.id DESC")->fetchAll();page_header('Users & Role Access');if($err)echo '<div class="notice error">'.e($err).'</div>'; ?>
<div class="notice"><b>Security:</b> Staff/report users must have assigned locations. No location = no stock/report access. Purchase cost remains Super Admin only.</div>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row3"><div><label>Name</label><input name="name" required></div><div><label>Username</label><input name="username" required></div><div><label>Password</label><input type="password" name="password" minlength="10" required></div></div><br><div class="row"><div><label>Role</label><select name="role" required><option value="cashier">Cashier</option><option value="godown">Godown</option><option value="manager">Manager</option><option value="auditor">Auditor</option></select></div><div><label>Assigned Locations</label><select name="locations[]" multiple size="5" required><?php foreach($locs as $l):?><option value="<?=$l['id']?>"><?=e($l['code'].' · '.$l['name'])?></option><?php endforeach;?></select></div></div><br><button class="btn">Create User</button></form><br>
<table><tr><th>Name</th><th>Username</th><th>Role</th><th>Assigned Locations</th><th>Status</th><th>Last Login</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['username'])?></td><td><?=e($r['role'])?></td><td><?=e($r['locations']?:($r['role']==='super_admin'?'ALL':'No locations assigned'))?></td><td><?= $r['active']?'Active':'Inactive' ?></td><td><?=e($r['last_login_at'])?></td><td><a href="user_edit.php?id=<?=$r['id']?>">Edit / Reset</a></td></tr><?php endforeach;?></table><?php page_footer();
